// Input Validation
const body = $input.first().json.body || $input.first().json;

const errors = [];
if (!body.full_name || body.full_name.trim().length < 2) errors.push('full_name required');
if (!body.email || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(body.email)) errors.push('valid email required');
if (!body.symptoms || body.symptoms.trim().length < 5) errors.push('symptoms required (min 5 chars)');
if (body.age && (parseInt(body.age) < 0 || parseInt(body.age) > 150)) errors.push('invalid age');

if (errors.length > 0) {
  return [{ json: { valid: false, errors, status: 400 } }];
}

// Sanitize
return [{ json: {
  valid: true,
  full_name: body.full_name.trim(),
  email: body.email.trim().toLowerCase(),
  symptoms: body.symptoms.trim(),
  date_of_birth: body.date_of_birth || null,
  age: body.age ? parseInt(body.age) : null,
  phone: (body.phone || '').trim(),
  severity: body.severity || 'MILD',
  symptom_duration: body.symptom_duration || '',
  existing_conditions: body.existing_conditions || '',
  current_medications: body.current_medications || '',
  allergies: body.allergies || '',
  preferred_appointment_time: body.preferred_appointment_time || '',
  preferred_communication: body.preferred_communication || 'email',
  correlation_id: require('crypto').randomUUID()
}}];

