// Quick Safety Pre-Scan (deterministic)
const symptoms = ($input.first().json.symptoms || '').toLowerCase();

const EMERGENCY_PATTERNS = [
  /chest\s*(pain|pressure|tightness)/i,
  /heart\s*attack/i,
  /(severe|significant)\s*(difficulty|trouble)\s*(breathing|breath)/i,
  /can\s*'?t\s*breathe/i,
  /stroke/i,
  /loss\s*of\s*consciousness/i,
  /suicid/i,
  /self[\s-]*harm/i,
  /anaphyla/i,
  /(severe|heavy|uncontrolled)\s*bleed/i,
  /seizure|convulsion/i,
  /overdos/i,
];

const triggered = [];
for (const pattern of EMERGENCY_PATTERNS) {
  if (pattern.test(symptoms)) {
    triggered.push(pattern.toString());
  }
}

return [{ json: {
  ...$input.first().json,
  quick_scan: {
    has_emergency_indicators: triggered.length > 0,
    triggered_count: triggered.length,
    triggered_patterns: triggered
  }
}}];

