// Validate AI output
const output = $input.first().json.output || $input.first().json.text || '';
let parsed;
try {
  // Try direct parse
  parsed = JSON.parse(output);
} catch {
  // Try extracting from markdown
  const match = output.match(/```(?:json)?\s*\n?([\s\S]*?)\n?```/) || output.match(/\{[\s\S]*\}/);
  if (match) {
    try { parsed = JSON.parse(match[1] || match[0]); } catch { parsed = null; }
  }
}

if (!parsed) {
  return [{ json: { valid: false, error: 'Failed to parse AI output', raw: output.substring(0, 500) } }];
}

const VALID_URGENCY = ['EMERGENCY', 'URGENT', 'ROUTINE', 'NON_URGENT'];
const errors = [];
if (!VALID_URGENCY.includes(parsed.urgency)) errors.push('Invalid urgency');
if (typeof parsed.risk_score !== 'number' || parsed.risk_score < 0 || parsed.risk_score > 10) errors.push('Invalid risk_score');
if (!parsed.specialty) errors.push('Missing specialty');
if (!parsed.summary) errors.push('Missing summary');

if (errors.length > 0) {
  return [{ json: { valid: false, errors, parsed } }];
}

return [{ json: { valid: true, triage: parsed } }];

// DETERMINISTIC SAFETY ENGINE
// These rules CANNOT be overridden by AI
const body = $input.first().json.body || $input.first().json;
const symptoms = (body.symptoms || '').toLowerCase();
const triage = body.triage || {};

const EMERGENCY_PATTERNS = [
  { pattern: /chest\s*(pain|pressure|tightness)/i, category: 'cardiac', desc: 'Chest pain/pressure' },
  { pattern: /(severe|significant)\s*(difficulty|trouble)\s*(breathing)/i, category: 'respiratory', desc: 'Severe breathing difficulty' },
  { pattern: /can\s*'?t\s*breathe/i, category: 'respiratory', desc: 'Unable to breathe' },
  { pattern: /stroke/i, category: 'neurological', desc: 'Stroke symptoms' },
  { pattern: /loss\s*of\s*consciousness/i, category: 'neurological', desc: 'Loss of consciousness' },
  { pattern: /suicid/i, category: 'mental_health', desc: 'Suicidal ideation' },
  { pattern: /self[\s-]*harm/i, category: 'mental_health', desc: 'Self-harm' },
  { pattern: /anaphyla/i, category: 'allergic', desc: 'Anaphylaxis' },
  { pattern: /(severe|heavy|uncontrolled)\s*bleed/i, category: 'hemorrhagic', desc: 'Severe bleeding' },
  { pattern: /seizure|convulsion/i, category: 'neurological', desc: 'Seizure' },
  { pattern: /overdos/i, category: 'toxicological', desc: 'Overdose' },
];

const allText = `${symptoms} ${(triage.summary || '').toLowerCase()} ${(triage.red_flags || []).join(' ').toLowerCase()}`;
const triggered = [];

for (const rule of EMERGENCY_PATTERNS) {
  if (rule.pattern.test(allText)) {
    triggered.push({ category: rule.category, description: rule.desc });
  }
}

const riskEmergency = (triage.risk_score || 0) >= 8;
const aiEmergency = triage.urgency === 'EMERGENCY';
const keywordEmergency = triggered.length > 0;
const isEmergency = keywordEmergency || riskEmergency || aiEmergency;
const deterministicOverride = keywordEmergency && triage.urgency !== 'EMERGENCY';

return [{ json: {
  passed: !isEmergency,
  is_emergency: isEmergency,
  final_urgency: isEmergency ? 'EMERGENCY' : (triage.urgency || 'ROUTINE'),
  deterministic_override: deterministicOverride,
  requires_human_review: isEmergency || (triage.requires_human_review === true),
  triggered_rules: triggered,
  risk_score: triage.risk_score || 0
}}];
